root = Path.cwd().resolve()
# Verifier toutes les preconditions avant de modifier le moindre fichier.
for entry in ENTRIES:
    path = (root / entry['path']).resolve()
    assert path.is_relative_to(root), entry['path']
    current = hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None
    assert current == entry['old_sha256'], f"Fichier modifie depuis la validation: {entry['path']}"
    assert hashlib.sha256(entry['content'].encode()).hexdigest() == entry['new_sha256']
for entry in ENTRIES:
    path = root / entry['path']
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(entry['content'].encode())
print('Integration Runway: 7 fichiers appliques, contenus controles.')
